/* ============================================================
   2) POSIÇÕES DOS CAMPOS (mesmas do Python)
   ============================================================ */
var FIELD_POSITIONS = {
  nome:     [80, 40],
  livro:    [80, 72],
  capitulo: [108, 105],
  verso:    [240, 105],
  date:     [228, 170],
  aux:      [108, 198],
  text:     [30, 250]
};

/* ============================================================
   3) CONFIGURAÇÕES
   ============================================================ */
var VERSION     = 'acf';
var FONT_SIZE   = 18;
var FONT_FAMILY = 'Arial, Helvetica, sans-serif';
var MAX_CHARS   = 40;
var LINE_GAP    = 4;

/* Troque pelo endpoint do SEU servidor em produção */
var CORS_PROXY = 'https://api.allorigins.win/raw?url=';

/* ============================================================
   4) TEMPLATE BASE64  ← 👇 COLE O SEU AQUI 👇
   Use aspas duplas. Cole em UMA LINHA (sem quebras).
   ============================================================ */
var TEMPLATE_BASE64 = ''
console.log('[ficha.js] v3 carregado — fetch por capítulo');

/* ============================================================
   5) ESTADO GLOBAL
   ============================================================ */
var templateImage = null;
var generating    = false;

/* ============================================================
   6) HELPERS BÁSICOS
   ============================================================ */
function $(id) { return document.getElementById(id); }

function getBookAbbrev(name) {
  var key = (name || '').trim();
  return Object.prototype.hasOwnProperty.call(STATIC_BOOK_MAP, key)
    ? STATIC_BOOK_MAP[key] : null;
}

function parseVerseRange(str) {
  str = (str || '').trim();
  if (!str) return [];

  str = str.replace(/\s+/g, '');
  var parts = str.split(',');
  var verses = [];

  for (var i = 0; i < parts.length; i++) {
    var part = parts[i];
    if (!part) continue;

    if (part.indexOf('-') !== -1) {
      var bounds = part.split('-');
      var a = parseInt(bounds[0], 10);
      var b = parseInt(bounds[1], 10);
      if (!isNaN(a) && !isNaN(b) && a <= b) {
        for (var j = a; j <= b; j++) verses.push(j);
      }
    } else {
      var n = parseInt(part, 10);
      if (!isNaN(n)) verses.push(n);
    }
  }

  var seen = {}, out = [];
  for (var k = 0; k < verses.length; k++) {
    if (!seen[verses[k]]) { seen[verses[k]] = 1; out.push(verses[k]); }
  }
  out.sort(function (x, y) { return x - y; });
  return out;
}

function parseNames(str) {
  if (!str || !str.trim()) return [];
  var parts = str.split(',');
  var result = [];
  for (var i = 0; i < parts.length; i++) {
    var name = parts[i].trim();
    if (name) result.push(name);
  }
  return result;
}

function safeFilename(name) {
  return name.replace(/[<>:"/\\|?*]/g, '_');
}

/* ============================================================
   7) HELPERS DE UI
   ============================================================ */
function setMessage(text, type) {
  var el = $('message');
  el.textContent = text;
  el.className = 'message ' + (type || '');
}
function setStatus(text) { $('status').textContent = text; }

function showProgress(active, indeterminate, value) {
  var p = $('progress');
  var b = $('progressBar');
  if (active) p.classList.add('active'); else p.classList.remove('active');

  if (indeterminate) {
    p.classList.add('indeterminate');
    b.style.width = '';
  } else {
    p.classList.remove('indeterminate');
    b.style.width = ((value || 0) * 100) + '%';
  }
}

function nextFrame() {
  return new Promise(function (res) {
    requestAnimationFrame(function () { res(); });
  });
}

/* ============================================================
   8) TEMPLATE
   ============================================================ */
function loadTemplate() {
  return new Promise(function (resolve, reject) {
    var img = new Image();
    img.onload  = function () { resolve(img); };
    img.onerror = function () { reject(new Error('Falha ao carregar o template')); };
    img.src = 'data:image/png;base64,' + TEMPLATE_BASE64.replace(/\s+/g, '');
  });
}

/* ============================================================
   9) PARSE DO CAPÍTULO — extrai { 1: "texto", 2: "texto", ... }
   ============================================================ */
function parseChapterVerses(html) {
  var doc = new DOMParser().parseFromString(html, 'text/html');
  var all = doc.querySelectorAll('p[data-v]');
  var best = {};   // { n: { text: "...", score: N } }

  for (var i = 0; i < all.length; i++) {
    var el = all[i];

    /* Exige data-v=".N." */
    var dv = (el.getAttribute('data-v') || '').trim();
    var m = dv.match(/^\.(\d+)\.$/);
    if (!m) continue;

    var clone = el.cloneNode(true);

    var verseNumber = clone.querySelector('[data-vn]');
    if (verseNumber) verseNumber.remove();

    var verseMarker = clone.querySelector('[data-vb]');
    if (verseMarker) verseMarker.remove();

    var text = clone.textContent
      .replace(/\s+/g, ' ')
      .trim();

    if (!text) continue;

    text = text.replace(/^\d+\s+/, '').trim();

    var n = parseInt(m[1], 10);

    var score = text.length;

    if (!best[n] || best[n].score < score) {
      best[n] = {
        text: text,
        score: score
      };
    }
  }

  /* Extrai somente o texto do mapa final */
  var map = {};

  for (var k in best) {
    map[k] = best[k].text;
  }

  return map;
}

