function fetchWithTimeout(url, ms) {
  return new Promise(function (resolve, reject) {
    var ctrl = new AbortController();

    var timer = setTimeout(function () {
      ctrl.abort();
      reject(new Error('timeout após ' + ms + 'ms'));
    }, ms);

    fetch(url, {
      signal: ctrl.signal,
      cache: 'no-store'
    })
      .then(function (r) {
        clearTimeout(timer);
        resolve(r);
      })
      .catch(function (e) {
        clearTimeout(timer);
        reject(e);
      });
  });
}

function fetchOnce(target, proxy) {
  var url = proxy + encodeURIComponent(target);

  console.log('[ficha.js] Tentando proxy:', proxy);
  console.log('[ficha.js] URL alvo:', target);

  return fetchWithTimeout(url, 20000)
    .then(function (r) {

      console.log(
        '[ficha.js] Resposta:',
        proxy,
        'HTTP',
        r.status
      );

      if (!r.ok) {
        throw new Error('HTTP ' + r.status);
      }

      return r.text();
    })
    .then(function (html) {

      if (!html || html.length < 100) {
        throw new Error(
          'Resposta vazia ou muito pequena (' +
          (html ? html.length : 0) +
          ' caracteres)'
        );
      }

      console.log(
        '[ficha.js] HTML recebido com sucesso:',
        html.length,
        'caracteres'
      );

      return html;
    });
}

function fetchChapterHtml(livro, capitulo) {

  var abbrev = getBookAbbrev(livro);

  if (!abbrev) {
    return Promise.reject(
      new Error('Livro "' + livro + '" não encontrado')
    );
  }

  var target =
    'https://www.bibliaonline.com.br/' +
    VERSION +
    '/' +
    abbrev +
    '/' +
    capitulo;

  console.log(
    '[ficha.js] Buscando capítulo:',
    livro,
    capitulo
  );

  function tryProxy(i, attempt) {

    if (i >= CORS_PROXIES.length) {

      return Promise.reject(
        new Error(
          'Todos os proxies falharam. ' +
          'Verifique os erros acima no console.'
        )
      );
    }

    console.log(
      '[ficha.js] Proxy ' +
      (i + 1) +
      '/' +
      CORS_PROXIES.length +
      ' tentativa ' +
      attempt
    );

    return fetchOnce(target, CORS_PROXIES[i])

      .catch(function (err) {

        console.warn(
          '[ficha.js] Falha no proxy:',
          CORS_PROXIES[i],
          err
        );

        if (attempt < 2) {

          return new Promise(function (resolve) {
            setTimeout(resolve, 700);
          })
          .then(function () {
            return tryProxy(i, attempt + 1);
          });

        }

        return tryProxy(i + 1, 1);
      });
  }

  return tryProxy(0, 1);
}

/* ============================================================
   11) WRAP DE TEXTO
   ============================================================ */
function wrapText(text, width) {
  var result = [];
  var paragraphs = (text || '').split('\n');

  for (var p = 0; p < paragraphs.length; p++) {
    var paragraph = paragraphs[p];
    if (!paragraph) { result.push(''); continue; }

    var words = paragraph.split(/\s+/);
    var line = '';
    for (var w = 0; w < words.length; w++) {
      var word = words[w];
      if (!line) line = word;
      else if ((line + ' ' + word).length <= width) line += ' ' + word;
      else { result.push(line); line = word; }
    }
    if (line) result.push(line);
  }
  return result;
}

/* ============================================================
   12) MONTAGEM DA IMAGEM (síncrono, sem fetch)
   ============================================================ */
function buildImage(livro, capitulo, verso, nome, texto, dateStr, auxStr) {
  var canvas = document.createElement('canvas');
  canvas.width  = templateImage.naturalWidth;
  canvas.height = templateImage.naturalHeight;

  var ctx = canvas.getContext('2d');
  ctx.drawImage(templateImage, 0, 0);

  ctx.font = FONT_SIZE + 'px ' + FONT_FAMILY;
  ctx.fillStyle = '#000';
  ctx.textBaseline = 'top';

  var fields = {
    nome:     nome || '',
    livro:    String(livro),
    capitulo: String(capitulo),
    verso:    String(verso),
    date:     dateStr,
    aux:      auxStr
  };

  for (var k in fields) {
    if (!fields[k]) continue;
    var pos = FIELD_POSITIONS[k];
    if (pos) ctx.fillText(fields[k], pos[0], pos[1]);
  }

  if (texto) {
    var tp = FIELD_POSITIONS.text;
    var lines = wrapText(texto, MAX_CHARS);
    var m = ctx.measureText('Mg');
    var lh = (m.actualBoundingBoxAscent || FONT_SIZE * 0.8) +
             (m.actualBoundingBoxDescent || FONT_SIZE * 0.2);
    var y = tp[1];
    for (var i = 0; i < lines.length; i++) {
      ctx.fillText(lines[i], tp[0], y);
      y += lh + LINE_GAP;
    }
  }
  return canvas;
}

/* ============================================================
   13) RENDER DO RESULTADO
   ============================================================ */
function renderResult(canvas, filename) {
  var url = canvas.toDataURL('image/png');

  var item = document.createElement('div');
  item.className = 'result-item';

  var img = document.createElement('img');
  img.src = url;
  img.alt = filename;

  var info = document.createElement('div');
  info.className = 'info';
  info.textContent = filename;

  var link = document.createElement('a');
  link.className = 'dl';
  link.textContent = 'Baixar';
  link.download = filename;
  link.href = url;

  item.appendChild(img);
  item.appendChild(info);
  item.appendChild(link);
  $('results').appendChild(item);
}

/* ============================================================
   14) FINALIZAÇÃO
   ============================================================ */
function finishGeneration() {
  generating = false;
  $('generateBtn').disabled = false;
  setTimeout(function () { showProgress(false, false, 0); }, 300);
}

/* ============================================================
   15) AÇÃO PRINCIPAL
   ============================================================ */
function onGenerate() {
  if (generating) return;
  generating = true;
  $('generateBtn').disabled = true;
  $('results').innerHTML = '';
  setMessage('Iniciando geração...', 'info');
  showProgress(true, true, 0);

  var verseStr = $('verses').value.trim();
  if (!verseStr) {
    setMessage('❌ Informe pelo menos um verso', 'error');
    finishGeneration(); return;
  }
  var verses = parseVerseRange(verseStr);
  if (!verses.length) {
    setMessage('❌ Formato inválido. Use: 1, 1-10, 1,3,5', 'error');
    finishGeneration(); return;
  }
  var livro    = $('book').value.trim();
  var capitulo = $('chapter').value.trim();
  if (!livro || !capitulo) {
    setMessage('❌ Informe Livro e Capítulo', 'error');
    finishGeneration(); return;
  }

  var names    = parseNames($('names').value);
  var userText = $('text').value.trim();
  var dateStr  = $('date').value.trim();
  var auxStr   = $('aux').value.trim();

  var tplPromise = templateImage
    ? Promise.resolve()
    : loadTemplate().then(function (img) { templateImage = img; });

  var textPromise;
  if (userText) {
    textPromise = Promise.resolve(null);
  } else {
    setStatus('Buscando ' + livro + ' ' + capitulo + '...');
    textPromise = fetchChapterHtml(livro, capitulo).then(parseChapterVerses);
  }

  Promise.all([tplPromise, textPromise])
    .then(function (res) {
      var verseMap = res[1];
      var total    = verses.length;

      var i = 0;
      function step() {
        if (i >= total) return Promise.resolve();

        var verso = verses[i];
        var name  = (i < names.length) ? names[i] : '';
        var texto = userText ||
                    (verseMap ? verseMap[verso] : '') ||
                    ('Versículo ' + verso + ' não encontrado');

        setStatus('Gerando imagem ' + (i + 1) + ' de ' + total + ' (Verso ' + verso + ')...');
        showProgress(true, false, i / total);

        var canvas = buildImage(livro, capitulo, verso, name, texto, dateStr, auxStr);
        var filename = 'ficha_' + safeFilename(livro) + '_' + capitulo + '_' + verso + '.png';
        renderResult(canvas, filename);

        i++;
        return nextFrame().then(step);
      }

      return step().then(function () {
        showProgress(true, false, 1);
        setMessage(total === 1
          ? '✅ 1 imagem gerada com sucesso!'
          : '✅ ' + total + ' imagens geradas com sucesso!', 'success');
        setStatus('Pronto!');
      });
    })
    .catch(function (err) {
      console.error(err);
      setMessage('❌ Erro: ' + err.message, 'error');
      setStatus('');
    })
    .then(finishGeneration);
}

/* ============================================================
   16) INICIALIZAÇÃO
   ============================================================ */
document.addEventListener('DOMContentLoaded', function () {
  $('generateBtn').addEventListener('click', onGenerate);

  loadTemplate()
    .then(function (img) { templateImage = img; })
    .catch(function (e) { console.warn('Template:', e.message); });
});